<script setup>
import {computed} from 'vue';import {simulateRollout} from '../sim/models/rollout.mjs';import {useLabSession} from '../sim/session.mjs';
const s=useLabSession('evolution');const r=computed(()=>simulateRollout({rollout:s.rollout,compatibility:s.compatibility,schema:s.schema,strategy:s.strategy}));
</script><template><section class="sim-lab"><div class="sim-controls"><div><span>新版流量：{{s.rollout}}%</span><input v-model.number="s.rollout" type="range" min="0" max="100" step="10"></div><div><span>相容性</span><div class="sim-segment"><button :aria-pressed="s.compatibility" @click="s.compatibility=true">舊 consumer 可讀</button><button :aria-pressed="!s.compatibility" @click="s.compatibility=false">不相容</button></div></div><div><span>DB schema</span><div class="sim-segment"><button :aria-pressed="s.schema==='expanded'" @click="s.schema='expanded'">保留舊欄位</button><button :aria-pressed="s.schema==='contracted'" @click="s.schema='contracted'">已刪舊欄位</button></div></div></div><div class="rollout-bar"><div class="rollout-old" :style="{width:r.oldPct+'%'}">v1 {{r.oldPct}}%</div><div class="rollout-new" :style="{width:r.rollout+'%'}">v2 {{r.rollout}}%</div></div><div class="sim-system"><div :class="['sim-node',{'is-critical':r.incompatibleOldTraffic>0}]"><b>Old frontend</b><span>{{r.oldPct}}% traffic</span></div><div class="sim-arrow">↔</div><div class="sim-node"><b>Backend</b><span>old + new contract</span></div><div class="sim-arrow">↔</div><div :class="['sim-node',{'is-critical':s.schema==='contracted'&&r.oldPct>0}]"><b>Database</b><span>{{s.schema==='expanded'?'old + new s.schema':'new s.schema only'}}</span></div></div><div class="sim-metrics"><div><span>新版 exposure</span><strong>{{r.blastRadius}}%</strong></div><div :class="{'is-bad':r.affectedTraffic>0}"><span>受影響 traffic</span><strong>{{r.affectedTraffic}}%</strong></div><div><span>舊版仍在線</span><strong>{{r.oldPct}}%</strong></div><div :class="{'is-bad':!r.rollbackSafe}"><span>Code rollback</span><strong>{{r.rollbackSafe?'仍相容':'可能回不去'}}</strong></div></div><div :class="['sim-consequence',{'is-bad':!r.canPromote}]"><strong>{{r.canPromote?'目前可繼續觀察／放量':'先不要繼續放量'}}</strong><p>把 s.rollout 拉到 100% 前，先切換「不相容」或刪除舊欄位。你會看到 s.rollout strategy 只能限制 exposure，不能修復 contract 或 data s.compatibility。</p></div></section></template>